#!/bin/bash
set -e
S=$1; U=$2
COMMON=(-G Ninja -DCMAKE_BUILD_TYPE=Release -DBUILD_TESTING=OFF -DJPEGXL_ENABLE_TOOLS=ON -DJPEGXL_ENABLE_JPEGLI=OFF -DJPEGXL_ENABLE_SJPEG=OFF -DJPEGXL_ENABLE_OPENEXR=OFF -DJPEGXL_ENABLE_BENCHMARK=OFF -DJPEGXL_ENABLE_EXAMPLES=OFF -DJPEGXL_ENABLE_MANPAGES=OFF -DJPEGXL_ENABLE_DOXYGEN=OFF -DJPEGXL_ENABLE_JNI=OFF -DJPEGXL_ENABLE_VIEWERS=OFF -DJPEGXL_ENABLE_PLUGINS=OFF -DJPEGXL_ENABLE_DEVTOOLS=OFF -DJPEGXL_ENABLE_SKCMS=ON -DJPEGXL_BUNDLE_LIBPNG=OFF -DJPEGXL_FORCE_SYSTEM_BROTLI=OFF -DJPEGXL_FORCE_SYSTEM_HWY=OFF -DHWY_ENABLE_TESTS=OFF -DHWY_ENABLE_CONTRIB=OFF -DHWY_ENABLE_EXAMPLES=OFF -DBUILD_SHARED_LIBS=OFF)
rm -rf $S/cxx-simd $S/cxx-scalar
cmake -S $U -B $S/cxx-simd "${COMMON[@]}" -DCMAKE_CXX_FLAGS=-g1 -DCMAKE_C_FLAGS=-g1
cmake -S $U -B $S/cxx-scalar "${COMMON[@]}" "-DCMAKE_CXX_FLAGS=-g1 -DHWY_COMPILE_ONLY_SCALAR=1" "-DCMAKE_C_FLAGS=-g1 -DHWY_COMPILE_ONLY_SCALAR=1"
